using System.Text;
using System.Text.Json;
using System.Numerics;
using System.Security.Cryptography;

namespace AsmStone.Generator;

internal static class LlvmTablegenInventory
{
    private static readonly string[][] allowedExactOverlaps =
    [
        ["MSRpstateImm1", "MSRpstateImm4"],
    ];

    public static void EmitCSharp(string inputPath, string outputPath, string sourceCommit)
    {
        var inventory = Read(inputPath);
        ValidateExactOverlaps(inventory.Instructions);
        var inputSha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(inputPath))).ToLowerInvariant();
        var records = inventory.Instructions
            .Where(record => record.HasBits && !record.IsPseudo)
            .OrderByDescending(record => BitOperations.PopCount(record.Mask))
            .ThenBy(record => record.Value)
            .ThenBy(record => record.Name, StringComparer.Ordinal)
            .ToArray();
        var source = new StringBuilder(2_000_000);
        source.AppendLine("// <auto-generated />");
        source.AppendLine("// Generated from LLVM AArch64 TableGen JSON. Do not edit.");
        source.AppendLine($"// LLVM source commit: {sourceCommit}");
        source.AppendLine($"// TableGen JSON SHA-256: {inputSha256}");
        source.AppendLine("#nullable enable");
        source.AppendLine();
        source.AppendLine("namespace AsmStone.Generated;");
        source.AppendLine();
        source.AppendLine("internal static class A64GeneratedInstructionTable");
        source.AppendLine("{");
        source.AppendLine($"    internal const string SourceCommit = {Quote(sourceCommit)};");
        source.AppendLine($"    internal const string TablegenInputSha256 = {Quote(inputSha256)};");
        source.AppendLine($"    internal const int SourceRecordCount = {inventory.RecordCount};");
        source.AppendLine($"    internal const int SourceCompleteEncodingCount = {inventory.CompleteEncodingCount};");
        source.AppendLine($"    internal const int SourceOperandTypeCount = {inventory.Operands.Count};");
        source.AppendLine("    internal static readonly A64GeneratedInstruction[] All =");
        source.AppendLine("    [");
        foreach (var record in records)
        {
            source.Append("        new(");
            source.Append(Quote(record.Name));
            source.Append(", ");
            source.Append(Quote(Mnemonic(record.Assembly)));
            source.Append(", ");
            source.Append(Quote(record.Assembly));
            source.Append(", 0x");
            source.Append(record.Mask.ToString("X8"));
            source.Append("u, 0x");
            source.Append(record.Value.ToString("X8"));
            source.Append("u, ");
            source.Append(Flags(record));
            source.Append(", ");
            source.Append(Quote(record.DecoderMethod));
            source.Append(", ");
            source.Append(Quote(string.Join('|', record.Predicates)));
            source.Append(", ");
            source.Append(Quote(string.Join('|', record.VariableFields)));
            source.Append(", ");
            source.Append(Quote(FieldEncoding(record)));
            source.Append(", ");
            source.Append(Quote(OperandBindings(record)));
            source.Append(", ");
            source.Append(Quote(record.InputOperands ?? string.Empty));
            source.Append(", ");
            source.Append(Quote(record.OutputOperands ?? string.Empty));
            source.Append(", ");
            source.Append(Quote(record.Constraints));
            source.Append(", ");
            source.Append(record.HasCompleteEncoding ? "true" : "false");
            source.AppendLine("),");
        }

            source.AppendLine("    ];");
            source.AppendLine();
            source.AppendLine("    internal static bool TryGetExact(uint encoding, out int index)");
            source.AppendLine("    {");
            source.AppendLine("        switch (encoding)");
            source.AppendLine("        {");
            for (var index = 0; index < records.Length; index++)
            {
                if (records[index].Mask != uint.MaxValue)
                {
                    continue;
                }

                source.AppendLine($"            case 0x{records[index].Value:X8}u:");
                source.AppendLine($"                index = {index};");
                source.AppendLine("                return true;");
            }

            source.AppendLine("            default:");
            source.AppendLine("                index = -1;");
            source.AppendLine("                return false;");
            source.AppendLine("        }");
            source.AppendLine("    }");
            source.AppendLine("}");
            source.AppendLine();
            source.AppendLine("internal static class A64GeneratedOperandTable");
            source.AppendLine("{");
            source.AppendLine("    internal static readonly A64GeneratedOperand[] All =");
            source.AppendLine("    [");
            foreach (var operand in inventory.Operands)
            {
                source.Append("        new(");
                source.Append(Quote(operand.Name));
                source.Append(", ");
                source.Append(Quote(operand.OperandType));
                source.Append(", ");
                source.Append(Quote(operand.DecoderMethod));
                source.Append(", ");
                source.Append(Quote(operand.EncoderMethod));
                source.Append(", ");
                source.Append(Quote(operand.PrintMethod));
                source.Append(", ");
                source.Append(Quote(operand.ParserMatchClass));
                source.Append(", ");
                source.Append(Quote(operand.RegClass));
                source.Append(", ");
                source.Append(Quote(operand.ElementSize));
                source.Append(", ");
                source.Append(Quote(operand.Type));
                source.AppendLine("),");
            }

            source.AppendLine("    ];");
            source.AppendLine("}");
            Directory.CreateDirectory(Path.GetDirectoryName(outputPath)!);
        File.WriteAllText(outputPath, source.ToString());
        EmitTypedFieldTable(records, outputPath);
        EmitTypedPredicateTable(records, outputPath);
        EmitTypedBindingTable(records, inventory.Operands, outputPath);
        EmitTypedMemoryTable(records, outputPath);
    }

    private static void EmitIndexedSwitch<T>(
        StringBuilder source,
        IReadOnlyList<T> values,
        string returnType,
        Func<T, string> literal)
    {
        const int blockSize = 256;
        var blockCount = (values.Count + blockSize - 1) / blockSize;
        source.AppendLine($"    internal static {returnType} Get(int index)");
        source.AppendLine("    {");
        source.AppendLine("        return (index >> 8) switch");
        source.AppendLine("        {");
        for (var block = 0; block < blockCount; block++)
        {
            source.AppendLine($"            {block} => GetBlock{block}(index & 0xFF),");
        }

        source.AppendLine("            _ => throw new ArgumentOutOfRangeException(nameof(index)),");
        source.AppendLine("        };");
        source.AppendLine("    }");
        source.AppendLine();

        for (var block = 0; block < blockCount; block++)
        {
            var start = block * blockSize;
            var end = Math.Min(start + blockSize, values.Count);
            source.AppendLine($"    private static {returnType} GetBlock{block}(int index)");
            source.AppendLine("    {");
            source.AppendLine("        return index switch");
            source.AppendLine("        {");
            for (var index = start; index < end; index++)
            {
                source.AppendLine($"            {index - start} => {literal(values[index])},");
            }

            source.AppendLine("            _ => throw new ArgumentOutOfRangeException(nameof(index)),");
            source.AppendLine("        };");
            source.AppendLine("    }");
            source.AppendLine();
        }
    }

    private static void EmitTypedPredicateTable(
        IReadOnlyList<LlvmInstructionRecord> records,
        string outputPath)
    {
        var typedPath = Path.Combine(
            Path.GetDirectoryName(outputPath)!,
            "A64GeneratedPredicateTable.cs");
        var source = new StringBuilder(records.Count * 48);
        source.AppendLine("// <auto-generated />");
        source.AppendLine("// Generated from LLVM AArch64 TableGen JSON. Do not edit.");
        source.AppendLine("#nullable enable");
        source.AppendLine();
        source.AppendLine("namespace AsmStone.Generated;");
        source.AppendLine();
        source.AppendLine("internal static class A64GeneratedPredicateTable");
        source.AppendLine("{");
        EmitIndexedSwitch(
            source,
            records,
            "string[]",
            record => record.Predicates.Count == 0
                ? "Array.Empty<string>()"
                : $"[{string.Join(", ", record.Predicates.Select(Quote))}]");
        source.AppendLine("}");
        File.WriteAllText(typedPath, source.ToString());
    }

    private static void EmitTypedMemoryTable(
        IReadOnlyList<LlvmInstructionRecord> records,
        string outputPath)
    {
        var typedPath = Path.Combine(
            Path.GetDirectoryName(outputPath)!,
            "A64GeneratedMemoryTable.cs");
        var source = new StringBuilder(records.Count * 120);
        source.AppendLine("// <auto-generated />");
        source.AppendLine("// Generated from LLVM AArch64 TableGen JSON. Do not edit.");
        source.AppendLine("#nullable enable");
        source.AppendLine();
        source.AppendLine("using AsmStone.Model;");
        source.AppendLine();
        source.AppendLine("namespace AsmStone.Generated;");
        source.AppendLine();
        source.AppendLine("internal static class A64GeneratedMemoryTable");
        source.AppendLine("{");
        EmitIndexedSwitch(
            source,
            records,
            "A64GeneratedMemoryBinding?",
            record => MemoryLiteral(record));
        source.AppendLine("}");
        File.WriteAllText(typedPath, source.ToString());
    }

    private static string MemoryLiteral(LlvmInstructionRecord record)
    {
        var bindings = record.Bindings.ToDictionary(
            binding => binding.Name,
            binding => binding.Type,
            StringComparer.Ordinal);

        var open = -1;
        var close = -1;
        string[] inside = [];
        for (var search = 0; ;)
        {
            var candidateOpen = record.Assembly.IndexOf('[', search);
            if (candidateOpen < 0)
            {
                break;
            }

            var candidateClose = record.Assembly.IndexOf(']', candidateOpen + 1);
            if (candidateClose < 0)
            {
                break;
            }

            var candidateInside = Placeholders(
                    record.Assembly[(candidateOpen + 1)..candidateClose])
                .Where(bindings.ContainsKey)
                .ToArray();
            if (candidateInside.Length != 0
                && IsGeneralRegister(bindings[candidateInside[0]]))
            {
                open = candidateOpen;
                close = candidateClose;
                inside = candidateInside;
                break;
            }

            search = candidateClose + 1;
        }

        if (open < 0)
        {
            return "null";
        }

        string? offset = null;
        string? index = null;
        string? modifier = null;
        foreach (var name in inside.Skip(1))
        {
            var type = bindings[name];
            if (IsImmediate(type))
            {
                if (offset is not null)
                {
                    return "null";
                }

                offset = name;
            }
            else if (IsRegister(type))
            {
                if (index is not null)
                {
                    return "null";
                }

                index = name;
            }
            else if (type.StartsWith("ro_", StringComparison.Ordinal))
            {
                modifier = name;
            }
        }

        var suffix = record.Assembly[(close + 1)..];
        var mode = suffix.TrimStart().StartsWith('!')
            ? "PreIndexed"
            : index is not null ? "RegisterOffset" : "Offset";
        if (suffix.Contains(',', StringComparison.Ordinal))
        {
            var suffixNames = Placeholders(suffix)
                .Where(bindings.ContainsKey)
                .ToArray();
            foreach (var name in suffixNames)
            {
                if (IsImmediate(bindings[name]))
                {
                    if (offset is not null)
                    {
                        return "null";
                    }

                    offset = name;
                }
                else if (IsRegister(bindings[name]))
                {
                    if (index is not null)
                    {
                        return "null";
                    }

                    index = name;
                }
            }

            if (suffixNames.Length != 0)
            {
                mode = "PostIndexed";
            }
        }

        var fixedOffset = ReadFixedOffset(record.Assembly[(open + 1)..close]);
        return $"new A64GeneratedMemoryBinding({Quote(inside[0])}, {NullableQuote(offset)}, {NullableQuote(index)}, {NullableQuote(modifier)}, {fixedOffset}L, A64MemoryAddressingMode.{mode})";
    }

    private static string NullableQuote(string? value) => value is null ? "null" : Quote(value);

    private static IEnumerable<string> Placeholders(string text)
    {
        for (var index = 0; index < text.Length; index++)
        {
            if (text[index] != '$' || index + 1 >= text.Length || !char.IsLetter(text[index + 1]))
            {
                continue;
            }

            var start = ++index;
            while (index + 1 < text.Length
                && (char.IsLetterOrDigit(text[index + 1]) || text[index + 1] == '_'))
            {
                index++;
            }

            yield return text[start..(index + 1)];
        }
    }

    private static bool IsGeneralRegister(string type) =>
        type.StartsWith("GPR", StringComparison.Ordinal)
        && !type.StartsWith("GPR32x", StringComparison.Ordinal);

    private static bool IsRegister(string type) =>
        type.StartsWith("GPR", StringComparison.Ordinal)
        || type.StartsWith("FPR", StringComparison.Ordinal)
        || type.StartsWith("V", StringComparison.Ordinal)
        || type.StartsWith("ZPR", StringComparison.Ordinal)
        || type.StartsWith("PPR", StringComparison.Ordinal)
        || type.StartsWith("PNR", StringComparison.Ordinal);

    private static bool IsImmediate(string type) =>
        type.StartsWith("simm", StringComparison.OrdinalIgnoreCase)
        || type.StartsWith("uimm", StringComparison.OrdinalIgnoreCase)
        || type.StartsWith("imm", StringComparison.OrdinalIgnoreCase)
        || type.StartsWith("timm", StringComparison.OrdinalIgnoreCase);

    private static long ReadFixedOffset(string text)
    {
        var marker = text.IndexOf('#');
        if (marker < 0) return 0;
        var start = marker + 1;
        var end = start;
        if (end < text.Length && text[end] == '-') end++;
        while (end < text.Length && char.IsDigit(text[end])) end++;
        return long.TryParse(text[start..end], out var value) ? value : 0;
    }

    private static void EmitTypedBindingTable(
        IReadOnlyList<LlvmInstructionRecord> records,
        IReadOnlyList<LlvmOperandRecord> operands,
        string outputPath)
    {
        var typedPath = Path.Combine(
            Path.GetDirectoryName(outputPath)!,
            "A64GeneratedBindingTable.cs");
        var codecs = operands.ToDictionary(operand => operand.Name, StringComparer.Ordinal);
        var source = new StringBuilder(records.Count * 900);
        source.AppendLine("// <auto-generated />");
        source.AppendLine("// Generated from LLVM AArch64 TableGen JSON. Do not edit.");
        source.AppendLine("#nullable enable");
        source.AppendLine();
        source.AppendLine("using AsmStone.Model;");
        source.AppendLine();
        source.AppendLine("namespace AsmStone.Generated;");
        source.AppendLine();
        source.AppendLine("internal static class A64GeneratedBindingTable");
        source.AppendLine("{");
        EmitIndexedSwitch(
            source,
            records,
            "A64GeneratedBindingData[]",
            record =>
            {
                var bindings = BuildTypedBindings(record, codecs);
                return bindings.Count == 0
                    ? "Array.Empty<A64GeneratedBindingData>()"
                    : $"[{string.Join(", ", bindings.Select(BindingLiteral))}]";
            });
        source.AppendLine("}");
        File.WriteAllText(typedPath, source.ToString());
    }

    private static string BindingLiteral(TypedBindingPlan binding)
    {
        var initializer = new StringBuilder("{ IsTypedPlan = true");
        AppendInt(initializer, "FieldIndex", binding.FieldIndex, -1);
        AppendInt(initializer, "SecondaryFieldIndex", binding.SecondaryFieldIndex, -1);
        AppendEnum(initializer, "Kind", binding.Kind, "EncodedField", "A64CompiledOperandKind");
        AppendInt(initializer, "FieldWidth", binding.FieldWidth, 0);
        AppendInt(initializer, "Scale", binding.Scale, 1);
        AppendInt(initializer, "RegisterWidth", binding.RegisterWidth, 0);
        AppendInt(initializer, "RegisterIndexBias", binding.RegisterIndexBias, 0);
        AppendInt(initializer, "RegisterIndexScale", binding.RegisterIndexScale, 1);
        AppendEnum(initializer, "RegisterClass", binding.RegisterClass, "Special", "A64RegisterClass");
        AppendBool(initializer, "AllowsStackPointer", binding.AllowsStackPointer);
        AppendBool(initializer, "AllowsZeroRegister", binding.AllowsZeroRegister);
        AppendConstraint(initializer, binding.RegisterConstraint);
        AppendInt(initializer, "ShapeCount", binding.ShapeCount, 0);
        AppendInt(initializer, "ElementWidth", binding.ElementWidth, 0);
        AppendInt(initializer, "GroupStride", binding.GroupStride, 1);
        AppendInt(initializer, "FractionalBits", binding.FractionalBits, 0);
        AppendInt(initializer, "LaneCount", binding.LaneCount, 0);
        AppendBool(initializer, "IsPageRelative", binding.IsPageRelative);
        AppendInt(initializer, "PcRelativeScale", binding.PcRelativeScale, 0);
        AppendBool(initializer, "IsSigned", binding.IsSigned);
        AppendEnum(initializer, "ImmediateSemanticKind", binding.ImmediateSemanticKind, "Plain", "A64ImmediateSemanticKind");
        AppendEnum(initializer, "EnumKind", binding.EnumKind, "Unknown", "A64EnumKind");
        AppendString(initializer, "SemanticDomain", binding.SemanticDomain);
        AppendEnum(initializer, "MatrixRegisterKind", binding.MatrixRegisterKind, "Za", "A64MatrixRegisterKind");
        AppendEnum(initializer, "FixedModifierKind", binding.FixedModifierKind, "Unknown", "A64RegisterModifierKind");
        AppendInt(initializer, "FixedModifierAmount", binding.FixedModifierAmount, 0);
        initializer.Append(" }");

        return "new A64GeneratedBindingData("
            + Quote(binding.Name)
            + ", "
            + Quote(binding.Type)
            + ", A64OperandDirection."
            + binding.Direction
            + ", "
            + NullableQuote(binding.TiedTo)
            + ", A64PredicateMode."
            + binding.PredicateMode
            + ") "
            + initializer;
    }

    private static void AppendInt(StringBuilder source, string name, int value, int defaultValue)
    {
        if (value == defaultValue) return;
        source.Append(", ");
        source.Append(name);
        source.Append(" = ");
        source.Append(value);
    }

    private static void AppendBool(StringBuilder source, string name, bool value)
    {
        if (!value) return;
        source.Append(", ");
        source.Append(name);
        source.Append(" = true");
    }

    private static void AppendString(StringBuilder source, string name, string value)
    {
        if (value.Length == 0) return;
        source.Append(", ");
        source.Append(name);
        source.Append(" = ");
        source.Append(Quote(value));
    }

    private static void AppendEnum(
        StringBuilder source,
        string name,
        string value,
        string defaultValue,
        string enumType)
    {
        if (value == defaultValue) return;
        source.Append(", ");
        source.Append(name);
        source.Append(" = ");
        source.Append(enumType);
        source.Append('.');
        source.Append(value);
    }

    private static void AppendConstraint(
        StringBuilder source,
        RegisterConstraintPlan constraint)
    {
        if (constraint == RegisterConstraintPlan.Any) return;
        source.Append(", RegisterConstraint = new A64RegisterConstraint(");
        source.Append(constraint.MinimumIndex);
        source.Append(", ");
        source.Append(constraint.MaximumIndex);
        source.Append(", ");
        source.Append(constraint.Step);
        source.Append(", 0x");
        source.Append(constraint.AllowedMask.ToString("X8"));
        source.Append("u)");
    }

    private static IReadOnlyList<TypedBindingPlan> BuildTypedBindings(
        LlvmInstructionRecord record,
        IReadOnlyDictionary<string, LlvmOperandRecord> codecs)
    {
        var fields = record.Fields;
        var ties = ParseBindingTies(record.Constraints, record.Bindings);
        var result = new List<TypedBindingPlan>(record.Bindings.Count);
        foreach (var binding in record.Bindings)
        {
            codecs.TryGetValue(binding.Type, out var codec);
            var fieldIndex = IndexOfField(fields, binding.Name);
            var secondaryFieldIndex = -1;
            var kind = ClassifyOperand(binding.Type, codec);
            var registerType = binding.Type;
            if (kind == "ModifiedRegister"
                && TryGetModifiedRegister(binding.Type, out var modified))
            {
                fieldIndex = IndexOfField(fields, modified.RegisterField);
                secondaryFieldIndex = IndexOfField(fields, modified.ModifierField);
                registerType = modified.RegisterType;
            }

            var shapeCount = 0;
            var elementWidth = 0;
            if (kind == "VectorList")
            {
                TryGetVectorList(binding.Type, out shapeCount, out elementWidth);
            }
            else if (kind == "RegisterGroup")
            {
                TryGetRegisterGroup(binding.Type, out shapeCount, out _);
                elementWidth = ElementWidth(binding.Type);
            }

            var matrixKind = TryGetMatrixRegister(
                binding.Type,
                out var parsedMatrixKind,
                out var matrixElementWidth)
                ? parsedMatrixKind
                : "Za";
            if (elementWidth == 0)
            {
                elementWidth = matrixElementWidth != 0
                    ? matrixElementWidth
                    : ElementWidth(binding.Type);
            }

            if (elementWidth == 0 && IsOptionalSveShift(binding.Type))
            {
                elementWidth = SveImmediateElementWidth(binding.Type);
            }

            var registerClass = RegisterClass(registerType);
            if (registerClass == "Predicate"
                && string.Equals(codec?.ElementSize, "ElementSizeNone", StringComparison.Ordinal))
            {
                elementWidth = 0;
            }

            var registerConstraint = TryGetRegisterConstraint(
                registerType,
                out var parsedConstraint)
                ? parsedConstraint
                : RegisterConstraintPlan.Any;
            result.Add(new TypedBindingPlan(
                binding.Name,
                binding.Type,
                Direction(binding.Direction),
                ties.GetValueOrDefault(binding.Name),
                PredicateMode(record.Assembly, binding.Name),
                fieldIndex,
                secondaryFieldIndex,
                kind,
                fieldIndex >= 0 ? FieldWidth(fields[fieldIndex]) : 32,
                ReadScale(binding.Type, codec?.PrintMethod ?? string.Empty),
                RegisterWidth(registerType),
                RegisterIndexBias(registerType),
                RegisterIndexScale(registerType),
                registerClass,
                registerType.Contains("sp", StringComparison.OrdinalIgnoreCase),
                AllowsZeroRegister(registerType),
                registerConstraint,
                shapeCount,
                elementWidth,
                GroupStride(binding.Type),
                FixedPointFractionalBits(binding.Type),
                LaneCount(binding.Type, elementWidth),
                binding.Type.Contains("adrplabel", StringComparison.OrdinalIgnoreCase),
                kind == "PcRelative"
                    ? binding.Type.Contains("adrplabel", StringComparison.OrdinalIgnoreCase) ? 12
                    : binding.Type.Contains("adrlabel", StringComparison.OrdinalIgnoreCase) ? 0 : 2
                    : 0,
                IsSigned(binding.Type, codec),
                ImmediateSemanticKind(binding.Type),
                EnumKind(binding.Type),
                binding.Type,
                matrixKind,
                FixedModifierKind(binding.Type),
                FixedModifierAmount(binding.Type)));
        }

        var contextualElementWidth = result
            .Where(binding => binding.RegisterClass == "SveVector")
            .Select(binding => binding.ElementWidth)
            .FirstOrDefault(width => width != 0);
        if (contextualElementWidth != 0)
        {
            return result
                .Select(binding => binding.RegisterClass == "Predicate"
                    && binding.ElementWidth == 0
                    ? binding with { ElementWidth = contextualElementWidth }
                    : binding)
                .ToArray();
        }

        return result;
    }

    private static int IndexOfField(
        IReadOnlyList<LlvmEncodingField> fields,
        string name)
    {
        for (var index = 0; index < fields.Count; index++)
        {
            if (string.Equals(fields[index].Name, name, StringComparison.Ordinal))
            {
                return index;
            }
        }

        return -1;
    }

    private static int FieldWidth(LlvmEncodingField field)
    {
        return field.Bits.Count == 0
            ? 0
            : field.Bits.Max(bit => bit.FieldBit) + 1;
    }

    private static string ClassifyOperand(
        string type,
        LlvmOperandRecord? codec)
    {
        if (TryGetModifiedRegister(type, out _)) return "ModifiedRegister";
        if (type == "arith_extendlsl64") return "RegisterModifier";
        if (type == "hinte_uimm16") return "Immediate";
        if (type is "mrs_sysreg_op" or "msr_sysreg_op") return "SystemRegister";
        if (type == "MatrixTileList") return "MatrixTileMask";
        if (TryGetMatrixRegister(type, out _, out _)) return "MatrixRegister";
        if (TryGetRegisterPair(type, out _, out _)) return "RegisterPair";
        if (type is "logical_imm32" or "logical_imm64") return "LogicalImmediate";
        if (type == "simdimmtype10") return "SimdImmediate";
        if (type == "movimm32_imm") return "MoveWideImmediate";
        if (type is "movimm32_shift" or "movimm64_shift") return "MoveWideShift";
        if (IsFloatingImmediate(type)) return "FloatingImmediate";
        if (IsVectorShift(type)) return "VectorShift";
        if (type == "sve_incdec_imm") return "SveIncrement";
        if (IsBitIndex(type)) return "BitIndex";
        if (IsEncodedEnum(type)) return "EnumImmediate";
        if (TryGetVectorList(type, out _, out _)) return "VectorList";
        if (TryGetRegisterGroup(type, out _, out _)) return "RegisterGroup";
        if (codec?.OperandType == "OPERAND_PCREL") return "PcRelative";
        if (codec is not null && IsRegisterType(type)) return "Register";
        if (codec is not null && IsImmediateType(type, codec)) return "Immediate";
        return "EncodedField";
    }

    private static bool IsRegisterType(string type)
    {
        return type.StartsWith("GPR", StringComparison.Ordinal)
            || type.StartsWith("FPR", StringComparison.Ordinal)
            || type.StartsWith("V", StringComparison.Ordinal)
                && !type.StartsWith("VectorIndex", StringComparison.Ordinal)
            || type.StartsWith("ZPR", StringComparison.Ordinal)
            || type.StartsWith("PPR", StringComparison.Ordinal)
            || type.StartsWith("PNR", StringComparison.Ordinal)
            || type.StartsWith("Z_", StringComparison.Ordinal)
            || type.StartsWith("MatrixIndexGPR", StringComparison.Ordinal);
    }

    private static bool IsImmediateType(string type, LlvmOperandRecord codec)
    {
        return codec.OperandType is "OPERAND_IMMEDIATE"
            or "OPERAND_SHIFTED_IMMEDIATE"
            or "OPERAND_IMM_UINT8"
            or "OPERAND_IMM_UINT1"
            or "OPERAND_IMM_UINT4plus1"
            or "OPERAND_IMM_UINT5"
            or "OPERAND_IMPLICIT_IMM_0"
            || type.StartsWith("imm", StringComparison.OrdinalIgnoreCase)
            || type.StartsWith("simm", StringComparison.OrdinalIgnoreCase)
            || type.StartsWith("uimm", StringComparison.OrdinalIgnoreCase)
            || type.Contains("Imm", StringComparison.Ordinal);
    }

    private static bool IsSigned(string type, LlvmOperandRecord? codec)
    {
        return type.StartsWith("simm", StringComparison.OrdinalIgnoreCase)
            || codec?.ParserMatchClass.StartsWith("SImm", StringComparison.Ordinal) == true;
    }

    private static int RegisterWidth(string type)
    {
        if (TryGetRegisterPair(type, out _, out var pairWidth)) return pairWidth;
        if (type.StartsWith("ZPR", StringComparison.Ordinal)
            || type.StartsWith("ZZ", StringComparison.Ordinal)
            || type.StartsWith("Z_", StringComparison.Ordinal))
        {
            return ElementWidth(type);
        }

        if (type.StartsWith("PPR", StringComparison.Ordinal)
            || type.StartsWith("PNR", StringComparison.Ordinal))
        {
            return 0;
        }

        var start = type.StartsWith("GPR", StringComparison.Ordinal)
            || type.StartsWith("FPR", StringComparison.Ordinal) ? 3
            : type.StartsWith("MatrixIndexGPR", StringComparison.Ordinal) ? "MatrixIndexGPR".Length
            : type.StartsWith("V", StringComparison.Ordinal) ? 1
            : 0;
        var width = 0;
        while (start != 0 && start < type.Length && char.IsDigit(type[start]))
        {
            width = width * 10 + type[start++] - '0';
        }

        return width;
    }

    private static string RegisterClass(string type)
    {
        if (type.Contains("asZPR", StringComparison.Ordinal)) return "SveVector";
        if (type.StartsWith("PP_", StringComparison.Ordinal)) return "Predicate";
        if (TryGetRegisterPair(type, out var pairClass, out _)) return pairClass;
        if (type.StartsWith("GPR", StringComparison.Ordinal)
            || type.StartsWith("MatrixIndexGPR", StringComparison.Ordinal)) return "General";
        if (type.StartsWith("FPR", StringComparison.Ordinal)) return "FloatingPoint";
        if (type.StartsWith("V", StringComparison.Ordinal)) return "Vector";
        if (type.StartsWith("ZPR", StringComparison.Ordinal)
            || type.StartsWith("ZZ", StringComparison.Ordinal)
            || type.StartsWith("Z_", StringComparison.Ordinal)) return "SveVector";
        if (type.StartsWith("PPR", StringComparison.Ordinal)
            || type.StartsWith("PNR", StringComparison.Ordinal)) return "Predicate";
        return "Special";
    }

    private static int LaneCount(string type, int elementWidth)
    {
        if (!type.StartsWith("VectorIndex", StringComparison.Ordinal)
            && !IsSveExtendedDuplicateIndex(type)) return 0;
        if (type.Contains("timm", StringComparison.OrdinalIgnoreCase)) return 0;
        if (IsSveExtendedDuplicateIndex(type))
        {
            return elementWidth switch
            {
                8 => 64,
                16 => 32,
                32 => 16,
                64 => 8,
                128 => 4,
                _ => 0,
            };
        }

        return elementWidth switch
        {
            8 => 16,
            16 => 8,
            32 => 4,
            64 => 2,
            _ => 0,
        };
    }

    private static string ImmediateSemanticKind(string type)
    {
        if (IsEncodedEnum(type)) return "Enum";
        if (type is "logical_imm32" or "logical_imm64") return "LogicalImmediate";
        if (type == "simdimmtype10") return "SimdImmediate";
        if (IsFloatingImmediate(type)) return "FloatingImmediate";
        if (IsOptionalSveShift(type)) return "SveOptionalShift";
        if (type == "hinte_uimm16") return "HinteImmediate";
        if (type == "movimm32_imm") return "MoveWideImmediate";
        if (type == "sve_incdec_imm") return "SveIncrement";
        if (IsBitIndex(type)) return "BitIndex";
        if (type.StartsWith("VectorIndex", StringComparison.Ordinal)
            || IsSveExtendedDuplicateIndex(type)) return "LaneIndex";
        if (type.StartsWith("complexrotate", StringComparison.Ordinal)) return "ComplexRotation";
        if (type.StartsWith("fixedpoint", StringComparison.Ordinal)) return "FixedPoint";
        return type.Contains("shift", StringComparison.OrdinalIgnoreCase) ? "Shift" : "Plain";
    }

    private static string EnumKind(string type)
    {
        return type switch
        {
            "sve_pred_enum" => "SvePredicatePattern",
            "sve_prfop" => "SvePrefetch",
            "sve_vec_len_specifier_enum" => "SveVectorLength",
            "svcr_op" => "Svcr",
            "TIndexhint_op" => "TIndexHint",
            "ccode" or "inv_ccode" => "ConditionCode",
            "barrier_op" or "barrier_nxs_op" => "Barrier",
            "prfop" or "rprfop" => "Prefetch",
            "sys_cr_op" => "SystemControlRegister",
            "pstatefield1_op" or "pstatefield4_op" => "PStateField",
            _ => "Unknown",
        };
    }

    private static string FixedModifierKind(string type)
    {
        if (type.Contains("ExtUXTW", StringComparison.Ordinal)) return "Uxtw";
        if (type.Contains("ExtSXTW", StringComparison.Ordinal)) return "Sxtw";
        if (type.Contains("ExtLSL", StringComparison.Ordinal)) return "Lsl";
        return "Unknown";
    }

    private static int FixedModifierAmount(string type)
    {
        var marker = type.IndexOf("Ext", StringComparison.Ordinal);
        if (marker < 0) return 0;
        var index = marker + 3;
        while (index < type.Length && !char.IsDigit(type[index])) index++;
        var amount = 0;
        while (index < type.Length && char.IsDigit(type[index]))
        {
            amount = amount * 10 + type[index++] - '0';
        }

        return amount;
    }

    private static bool AllowsZeroRegister(string type)
    {
        return type.StartsWith("GPR32z", StringComparison.Ordinal)
            || type.StartsWith("GPR64z", StringComparison.Ordinal)
            || type is "GPR32" or "GPR64";
    }

    private static int ReadScale(string type, string printMethod)
    {
        if (TryReadAngleValue(printMethod, "Scale<", out var printScale)
            || TryReadAngleValue(printMethod, "scale<", out printScale))
        {
            return printScale;
        }

        var immediate = type.IndexOf("imm", StringComparison.OrdinalIgnoreCase);
        if (immediate >= 0)
        {
            var index = immediate + 3;
            while (index < type.Length && char.IsDigit(type[index])) index++;
            if (index < type.Length && (type[index] is 's' or 'S'))
            {
                index++;
                var start = index;
                var scale = 0;
                while (index < type.Length && char.IsDigit(type[index]))
                {
                    scale = scale * 10 + type[index++] - '0';
                }

                if (index != start && scale != 0) return scale;
            }
        }

        return 1;
    }

    private static bool TryReadAngleValue(string text, string marker, out int value)
    {
        var markerIndex = text.IndexOf(marker, StringComparison.Ordinal);
        if (markerIndex < 0)
        {
            value = 0;
            return false;
        }

        var index = markerIndex + marker.Length;
        value = 0;
        var start = index;
        while (index < text.Length && char.IsDigit(text[index]))
        {
            value = value * 10 + text[index++] - '0';
        }

        return index != start && index < text.Length && text[index] == '>';
    }

    private static int RegisterIndexBias(string type)
    {
        return type switch
        {
            "MatrixIndexGPR32Op8_11" or "PNR8_p8to15" or "PNR16_p8to15"
                or "PNR32_p8to15" or "PNR64_p8to15" or "PNRAny_p8to15" => 8,
            "MatrixIndexGPR32Op12_15" => 12,
            _ when type.Contains("Mul2_Hi", StringComparison.Ordinal)
                || type.Contains("mul_r_Hi", StringComparison.Ordinal) => 16,
            _ => 0,
        };
    }

    private static int RegisterIndexScale(string type)
    {
        if (type.StartsWith("ZZZZ", StringComparison.Ordinal)
            && type.Contains("mul_r", StringComparison.Ordinal)) return 4;
        if (type.Contains("Mul2", StringComparison.Ordinal)
            || type.Contains("mul_r", StringComparison.Ordinal)
            || type.StartsWith("PP_", StringComparison.Ordinal)
                && type.Contains("mul_r", StringComparison.Ordinal)) return 2;
        return 1;
    }

    private static int GroupStride(string type)
    {
        if (type.Contains("and_contiguous", StringComparison.OrdinalIgnoreCase)) return 0;
        if (type.Contains("strided", StringComparison.OrdinalIgnoreCase))
        {
            return type.StartsWith("ZZZZ", StringComparison.Ordinal) ? 4 : 8;
        }

        return 1;
    }

    private static int FixedPointFractionalBits(string type)
    {
        var marker = type.IndexOf("_f", StringComparison.Ordinal);
        if (marker < 0) return 0;
        var index = marker + 2;
        var value = 0;
        while (index < type.Length && char.IsDigit(type[index]))
        {
            value = value * 10 + type[index++] - '0';
        }

        return value;
    }

    private static bool IsBitIndex(string type) =>
        type is "tbz_imm0_31_diag" or "tbz_imm32_63";

    private static bool IsEncodedEnum(string type) =>
        type is "sve_pred_enum"
            or "sve_vec_len_specifier_enum"
            or "sve_prfop"
            or "svcr_op"
            or "TIndexhint_op"
            or "barrier_op"
            or "barrier_nxs_op"
            or "ccode"
            or "inv_ccode"
            or "sys_cr_op"
            or "prfop"
            or "rprfop"
            or "pstatefield1_op"
            or "pstatefield4_op";

    private static bool IsFloatingImmediate(string type) =>
        type is "fpimm8" or "fpimm16" or "fpimm32" or "fpimm64" or "fpimmbf16"
            or "sve_fpimm_half_one" or "sve_fpimm_half_two" or "sve_fpimm_zero_one";

    private static bool IsVectorShift(string type) =>
        type.StartsWith("vecshiftL", StringComparison.Ordinal)
            || type.StartsWith("vecshiftR", StringComparison.Ordinal)
            || type is "logical_vec_shift" or "logical_vec_hw_shift" or "move_vec_shift";

    private static bool IsOptionalSveShift(string type) =>
        type.StartsWith("cpy_imm8_opt_lsl_i", StringComparison.Ordinal)
            || type.StartsWith("addsub_imm8_opt_lsl_i", StringComparison.Ordinal);

    private static int SveImmediateElementWidth(string type) => type[^2..] switch
    {
        "i8" => 8,
        "16" => 16,
        "32" => 32,
        "64" => 64,
        _ => 0,
    };

    private static bool IsSveExtendedDuplicateIndex(string type) =>
        type.StartsWith("sve_elm_idx_extdup_", StringComparison.Ordinal);

    private static int ElementWidth(string type)
    {
        if (type.StartsWith("VectorIndex", StringComparison.Ordinal)
            && type.Length > "VectorIndex".Length)
        {
            return type["VectorIndex".Length] switch
            {
                'B' => 8,
                'H' => 16,
                'S' => 32,
                'D' => 64,
                _ => 0,
            };
        }

        if (type.StartsWith("MatrixOp", StringComparison.Ordinal)
            || type.StartsWith("TileOp", StringComparison.Ordinal)
            || type.StartsWith("TileVectorOp", StringComparison.Ordinal)
            || type.StartsWith("ZPR", StringComparison.Ordinal)
            || type.StartsWith("PPR", StringComparison.Ordinal)
            || type.StartsWith("PNR", StringComparison.Ordinal)
            || type.Contains("asZPR", StringComparison.Ordinal))
        {
            var start = type.StartsWith("MatrixOp", StringComparison.Ordinal) ? "MatrixOp".Length
                : type.StartsWith("TileOp", StringComparison.Ordinal) ? "TileOp".Length
                : type.StartsWith("TileVectorOp", StringComparison.Ordinal) ? "TileVectorOp".Length
                : type.StartsWith("ZPR", StringComparison.Ordinal) ? "ZPR".Length
                : type.StartsWith("FPR", StringComparison.Ordinal) ? "FPR".Length
                : 3;
            while (start < type.Length && (type[start] is 'H' or 'V')) start++;

            var width = 0;
            while (start < type.Length && char.IsDigit(type[start]))
            {
                width = width * 10 + type[start++] - '0';
            }

            if (width is 8 or 16 or 32 or 64 or 128) return width;
            for (var index = start; index < type.Length; index++)
            {
                if (type[index] is 'b' or 'h' or 's' or 'd' or 'q')
                {
                    return type[index] switch
                    {
                        'b' => 8,
                        'h' => 16,
                        's' => 32,
                        'd' => 64,
                        'q' => 128,
                        _ => 0,
                    };
                }
            }
        }

        if (type.Contains("_b", StringComparison.Ordinal) || type.EndsWith('b')) return 8;
        if (type.Contains("_h", StringComparison.Ordinal) || type.EndsWith('h')) return 16;
        if (type.Contains("_s", StringComparison.Ordinal) || type.EndsWith('s')) return 32;
        if (type.Contains("_d", StringComparison.Ordinal) || type.EndsWith('d')) return 64;
        if (type.Contains("_q", StringComparison.Ordinal) || type.EndsWith('q')) return 128;
        return 0;
    }

    private static bool TryGetVectorList(
        string type,
        out int count,
        out int elementWidth)
    {
        count = type.StartsWith("VecListOne", StringComparison.Ordinal) ? 1
            : type.StartsWith("VecListTwo", StringComparison.Ordinal) ? 2
            : type.StartsWith("VecListThree", StringComparison.Ordinal) ? 3
            : type.StartsWith("VecListFour", StringComparison.Ordinal) ? 4 : 0;
        if (count == 0)
        {
            elementWidth = 0;
            return false;
        }

        var suffixStart = type.IndexOf("List", StringComparison.Ordinal) + 4
            + (count switch { 1 => 3, 2 => 3, 3 => 5, 4 => 4, _ => 0 });
        var suffix = type[suffixStart..];
        elementWidth = suffix.EndsWith('b') ? 8
            : suffix.EndsWith('h') ? 16
            : suffix.EndsWith('s') ? 32
            : suffix.EndsWith('d') ? 64 : 0;
        return elementWidth != 0;
    }

    private static bool TryGetModifiedRegister(
        string type,
        out ModifiedShape shape)
    {
        shape = type switch
        {
            "logical_shifted_reg32" or "arith_shifted_reg32"
                => new ModifiedShape("Rm", "shift", "GPR32"),
            "logical_shifted_reg64" or "arith_shifted_reg64"
                => new ModifiedShape("Rm", "shift", "GPR64"),
            "arith_extended_reg32_i32" or "arith_extended_reg32_i64"
                or "arith_extended_reg32to64_i64"
                => new ModifiedShape("Rm", "extend", "GPR32"),
            _ => default,
        };
        return shape.RegisterField is not null;
    }

    private static bool TryGetRegisterPair(
        string type,
        out string registerClass,
        out int registerWidth)
    {
        (registerClass, registerWidth) = type switch
        {
            "WSeqPairClassOperand" => ("General", 32),
            "XSeqPairClassOperand" or "MrrsMssrPairClassOperand" or "SyspXzrPairOperand"
                => ("General", 64),
            _ => ("Special", 0),
        };
        return registerWidth != 0;
    }

    private static bool TryGetMatrixRegister(
        string type,
        out string kind,
        out int elementWidth)
    {
        kind = type switch
        {
            "ZTR" => "Zt",
            "ZK" => "Zk",
            _ when type.StartsWith("MatrixOp", StringComparison.Ordinal) => "Za",
            _ when type.StartsWith("TileOp", StringComparison.Ordinal) => "Tile",
            _ when type.StartsWith("TileVectorOp", StringComparison.Ordinal) => "TileVector",
            _ => "Za",
        };
        elementWidth = ElementWidth(type);
        return type is "ZTR" or "ZK"
            || type.StartsWith("MatrixOp", StringComparison.Ordinal)
            || type.StartsWith("TileOp", StringComparison.Ordinal)
            || type.StartsWith("TileVectorOp", StringComparison.Ordinal);
    }

    private static bool TryGetRegisterGroup(
        string type,
        out int count,
        out string registerClass)
    {
        count = type.StartsWith("ZPR2", StringComparison.Ordinal) ? 2
            : type.StartsWith("ZPR4", StringComparison.Ordinal) ? 4
            : type.StartsWith("ZZZZ", StringComparison.Ordinal) ? 4
            : type.StartsWith("ZZZ", StringComparison.Ordinal) ? 3
            : type.StartsWith("ZZ", StringComparison.Ordinal) ? 2
            : type.StartsWith("PPR2", StringComparison.Ordinal) ? 2
            : type.StartsWith("PP_", StringComparison.Ordinal) ? 2 : 0;
        registerClass = type.StartsWith('P') ? "Predicate" : "SveVector";
        return count != 0;
    }

    private static bool TryGetRegisterConstraint(
        string type,
        out RegisterConstraintPlan constraint)
    {
        constraint = type switch
        {
            "ZK" => new RegisterConstraintPlan(20, 31, 1, (0xFu << 20) | (0xFu << 28)),
            "MatrixIndexGPR32Op8_11" => new RegisterConstraintPlan(8, 11, 1, 0),
            "MatrixIndexGPR32Op12_15" => new RegisterConstraintPlan(12, 15, 1, 0),
            "GPR32common" or "GPR64common" => new RegisterConstraintPlan(0, 30, 1, 0),
            "GPR64x8" => new RegisterConstraintPlan(0, 22, 2, 0),
            "V128_0to7" or "FPR128_0to7" => new RegisterConstraintPlan(0, 7, 1, 0),
            "V128_lo" or "V64_lo" or "FPR128_lo" or "FPR64_lo"
                => new RegisterConstraintPlan(0, 15, 1, 0),
            _ when type.StartsWith("ZPR3b", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 7, 1, 0),
            _ when type.StartsWith("ZPR4b", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 15, 1, 0),
            "PPR3bAny" => new RegisterConstraintPlan(0, 7, 1, 0),
            _ when type.StartsWith("PNR", StringComparison.Ordinal)
                && type.Contains("p8to15", StringComparison.Ordinal)
                => new RegisterConstraintPlan(8, 15, 1, 0),
            "WSeqPairClassOperand" or "XSeqPairClassOperand" or "MrrsMssrPairClassOperand"
                => new RegisterConstraintPlan(0, 30, 2, 0),
            _ when type.StartsWith("PP_", StringComparison.Ordinal)
                && type.Contains("mul_r", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 14, 2, 0),
            _ when type.StartsWith("ZZZZ", StringComparison.Ordinal)
                && type.Contains("mul_r", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 28, 4, 0),
            _ when type.StartsWith("ZZ", StringComparison.Ordinal)
                && type.Contains("mul_r", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 30, 2, 0),
            _ when type.StartsWith("ZZZZ", StringComparison.Ordinal)
                && type.Contains("strided", StringComparison.OrdinalIgnoreCase)
                && !type.Contains("and_contiguous", StringComparison.OrdinalIgnoreCase)
                => new RegisterConstraintPlan(0, 31, 1, 0x000F000Fu),
            _ when type.StartsWith("ZZ", StringComparison.Ordinal)
                && type.Contains("strided", StringComparison.OrdinalIgnoreCase)
                && !type.Contains("and_contiguous", StringComparison.OrdinalIgnoreCase)
                => new RegisterConstraintPlan(0, 31, 1, 0x00FF00FFu),
            _ when type.Contains("Mul2_Lo", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 14, 2, 0),
            _ when type.Contains("Mul2_Hi", StringComparison.Ordinal)
                => new RegisterConstraintPlan(16, 30, 2, 0),
            _ when (type.StartsWith("ZPR", StringComparison.Ordinal)
                    || type.StartsWith("ZZ", StringComparison.Ordinal))
                && type.Contains("_3b", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 7, 1, 0),
            _ when (type.StartsWith("ZPR", StringComparison.Ordinal)
                    || type.StartsWith("ZZ", StringComparison.Ordinal))
                && type.Contains("_4b", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 15, 1, 0),
            _ when type.Contains("_0to7", StringComparison.Ordinal)
                => new RegisterConstraintPlan(0, 7, 1, 0),
            _ when type.Contains("_lo", StringComparison.OrdinalIgnoreCase)
                => new RegisterConstraintPlan(0, 15, 1, 0),
            _ => RegisterConstraintPlan.Any,
        };
        return constraint != RegisterConstraintPlan.Any;
    }

    private static Dictionary<string, string> ParseBindingTies(
        string constraints,
        IReadOnlyList<LlvmOperandBinding> bindings)
    {
        var ties = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var constraint in constraints.Split(',', StringSplitOptions.RemoveEmptyEntries))
        {
            var equals = constraint.IndexOf('=');
            if (equals <= 0)
            {
                continue;
            }

            var left = constraint[..equals].Trim();
            var right = constraint[(equals + 1)..].Trim();
            if (left.StartsWith("@", StringComparison.Ordinal)
                || !left.StartsWith('$')
                || !right.StartsWith('$'))
            {
                continue;
            }

            left = left[1..];
            right = right.TrimStart('$');
            var separator = right.IndexOfAny([' ', '\t']);
            if (separator >= 0)
            {
                right = right[..separator];
            }

            right = right.TrimEnd(',');
            if (left.Length != 0 && right.Length != 0)
            {
                ties[left] = right;
                ties[right] = left;
            }
        }

        var names = bindings.Select(binding => binding.Name).ToHashSet(StringComparer.Ordinal);
        foreach (var binding in bindings)
        {
            if (binding.Name.StartsWith("_", StringComparison.Ordinal))
            {
                ties.TryAdd(binding.Name, binding.Name[1..]);
            }
            else if (binding.Name == "offset"
                && binding.Type == "imm32_0_15"
                && names.Contains("imm4"))
            {
                ties.TryAdd(binding.Name, "imm4");
            }
        }

        return ties;
    }

    private static string Direction(string direction)
    {
        return direction switch
        {
            "out" => "Output",
            "inout" => "InputOutput",
            _ => "Input",
        };
    }

    private static string PredicateMode(string assembly, string name)
    {
        var marker = "$" + name;
        var index = assembly.IndexOf(marker, StringComparison.Ordinal);
        if (index < 0 || index + marker.Length >= assembly.Length)
        {
            return "None";
        }

        var suffix = assembly.AsSpan(index + marker.Length);
        return suffix.StartsWith("/m", StringComparison.Ordinal)
            ? "Merge"
            : suffix.StartsWith("/z", StringComparison.Ordinal)
                ? "Zero"
                : "None";
    }

    private static void EmitTypedFieldTable(
        IReadOnlyList<LlvmInstructionRecord> records,
        string outputPath)
    {
        var typedPath = Path.Combine(
            Path.GetDirectoryName(outputPath)!,
            "A64GeneratedFieldTable.cs");
        var source = new StringBuilder(records.Count * 160);
        source.AppendLine("// <auto-generated />");
        source.AppendLine("// Generated from LLVM AArch64 TableGen JSON. Do not edit.");
        source.AppendLine("#nullable enable");
        source.AppendLine();
        source.AppendLine("namespace AsmStone.Generated;");
        source.AppendLine();
        source.AppendLine("internal static class A64GeneratedFieldTable");
        source.AppendLine("{");
        EmitIndexedSwitch(
            source,
            records,
            "A64GeneratedFieldData[]",
            record =>
            {
                if (record.Fields.Count == 0)
                {
                    return "Array.Empty<A64GeneratedFieldData>()";
                }

                var literals = record.Fields.Select(field =>
                    $"new A64GeneratedFieldData({Quote(field.Name)}, new A64GeneratedFieldMapping[] {{ "
                    + string.Join(
                        ", ",
                        field.Bits.Select(bit =>
                            $"new A64GeneratedFieldMapping({bit.EncodingBit}, {bit.FieldBit})"))
                    + " })");
                return "[" + string.Join(", ", literals) + "]";
            });
        source.AppendLine("}");
        File.WriteAllText(typedPath, source.ToString());
    }

    public static LlvmInventoryDocument Read(string path)
    {
        using var input = File.OpenRead(path);
        using var document = JsonDocument.Parse(input, new JsonDocumentOptions { MaxDepth = 512 });
        var root = document.RootElement;
        if (root.ValueKind != JsonValueKind.Object)
        {
            throw new InvalidDataException("The input is not an LLVM TableGen JSON document.");
        }

        var records = new List<LlvmInstructionRecord>();
        var names = new HashSet<string>(StringComparer.Ordinal);
        foreach (var property in root.EnumerateObject())
        {
            if (property.Value.ValueKind != JsonValueKind.Object
                || !IsAarch64Instruction(property.Value))
            {
                continue;
            }

            var name = OptionalString(property.Value, "!name") ?? property.Name;
            if (!names.Add(name))
            {
                throw new InvalidDataException($"Duplicate LLVM instruction record '{name}'.");
            }

            var encoding = ReadEncoding(property.Value);
            records.Add(new LlvmInstructionRecord(
                name,
                OptionalString(property.Value, "AsmString") ?? string.Empty,
                encoding.Mask,
                encoding.Value,
                encoding.HasBits,
                encoding.IsComplete,
                encoding.VariableFields,
                encoding.Fields,
                ReadOperandBindings(property.Value),
                OptionalString(property.Value, "DecoderMethod") ?? string.Empty,
                ReadStringList(property.Value, "Predicates"),
                ReadPrintable(property.Value, "InOperandList"),
                ReadPrintable(property.Value, "OutOperandList"),
                ReadString(property.Value, "Constraints"),
                ReadFlag(property.Value, "isPseudo"),
                ReadFlag(property.Value, "isCodeGenOnly"),
                ReadFlag(property.Value, "isAsmParserOnly"),
                ReadFlag(property.Value, "isBranch"),
                ReadFlag(property.Value, "isCall"),
                ReadFlag(property.Value, "isReturn"),
                ReadFlag(property.Value, "isCompare"),
                ReadFlag(property.Value, "isBarrier"),
                ReadFlag(property.Value, "isTerminator"),
                ReadFlag(property.Value, "hasSideEffects"),
                HasNamedRegister(property.Value, "Uses", "NZCV"),
                HasNamedRegister(property.Value, "Defs", "NZCV"),
                HasNamedRegister(property.Value, "Uses", "FPCR"),
                HasNamedRegister(property.Value, "Defs", "FPCR"),
                HasNamedRegister(property.Value, "Uses", "FFR"),
                HasNamedRegister(property.Value, "Defs", "FFR"),
                ReadFlag(property.Value, "mayRaiseFPException"),
                ReadNullableFlag(property.Value, "mayLoad"),
                ReadNullableFlag(property.Value, "mayStore"),
                ReadFlag(property.Value, "hasCompleteDecoder"),
                ReadStringList(property.Value, "!superclasses"),
                ReadStringList(property.Value, "!locs")));
        }

        if (records.Count == 0)
        {
            throw new InvalidDataException("The TableGen document contains no AArch64 instruction records.");
        }

        var encodable = records.Where(record => !record.IsPseudo && record.HasBits).ToArray();
        var complete = encodable.Where(record => record.HasCompleteEncoding).ToArray();
        var keys = complete
            .GroupBy(record => new EncodingKey(record.Mask, record.Value))
            .ToArray();
        var duplicateCount = keys.Sum(group => group.Count() - 1);
        var referencedOperandNames = records
            .SelectMany(record => record.Bindings.Select(binding => binding.Type))
            .ToHashSet(StringComparer.Ordinal);
        return new LlvmInventoryDocument(
            "LLVM.TableGen",
            records.Count,
            records.Count(record => !record.IsPseudo),
            records.Count(record => record.IsPseudo),
            encodable.Length,
            complete.Length,
            encodable.Length - complete.Length,
            keys.Length,
            duplicateCount,
            ReadOperands(root, referencedOperandNames),
            records.OrderBy(record => record.Name, StringComparer.Ordinal).ToArray());
    }

    private static bool IsAarch64Instruction(JsonElement record)
    {
        var superclasses = ReadStringList(record, "!superclasses");
        return superclasses.Contains("Instruction", StringComparer.Ordinal)
            && superclasses.Contains("AArch64Inst", StringComparer.Ordinal);
    }

    private static EncodingSummary ReadEncoding(JsonElement record)
    {
        var recordName = OptionalString(record, "!name");
        if (recordName is not null && TryReadSpecialEncoding(recordName, out var specialEncoding))
        {
            return specialEncoding;
        }

        if (!record.TryGetProperty("Inst", out var instructionBits)
            || instructionBits.ValueKind != JsonValueKind.Array
            || instructionBits.GetArrayLength() != 32)
        {
            return new EncodingSummary(0, 0, false, false, [], []);
        }

        uint mask = 0;
        uint value = 0;
        var fixedBits = 0;
        var complete = true;
        var fieldBits = new Dictionary<string, List<LlvmEncodingBit>>(StringComparer.Ordinal);
        var index = 0;
        foreach (var bit in instructionBits.EnumerateArray())
        {
            switch (bit.ValueKind)
            {
                case JsonValueKind.Number:
                    var fixedValue = bit.GetInt32();
                    if (fixedValue is not (0 or 1))
                    {
                        throw new InvalidDataException("An LLVM instruction has a non-binary fixed bit.");
                    }

                    mask |= 1u << index;
                    value |= (uint)fixedValue << index;
                    fixedBits++;
                    break;
                case JsonValueKind.Object:
                    var kind = OptionalString(bit, "kind");
                    var field = OptionalString(bit, "var");
                    if (kind == "var")
                    {
                        // Synthetic operands have no instruction-bit mapping.
                        break;
                    }

                    if (kind != "varbit"
                        || string.IsNullOrEmpty(field)
                        || !bit.TryGetProperty("index", out var indexElement)
                        || !indexElement.TryGetInt32(out var parsedIndex)
                        || parsedIndex is < 0 or > 31)
                    {
                        complete = false;
                        break;
                    }

                    if (!fieldBits.TryGetValue(field, out var mappings))
                    {
                        mappings = [];
                        fieldBits.Add(field, mappings);
                    }

                    mappings.Add(new LlvmEncodingBit(index, parsedIndex));

                    break;
                case JsonValueKind.Null:
                    complete = false;
                    break;
                default:
                    complete = false;
                    break;
            }

            index++;
        }

        AddSyntheticVariableMappings(instructionBits, fieldBits);

        return new EncodingSummary(
            mask,
            value,
            fixedBits != 0 || fieldBits.Count != 0,
            complete,
            fieldBits.Keys.OrderBy(field => field, StringComparer.Ordinal).ToArray(),
            fieldBits
                .OrderBy(pair => pair.Key, StringComparer.Ordinal)
                .Select(pair => new LlvmEncodingField(pair.Key, pair.Value.ToArray()))
            .ToArray());
    }

    private static void AddSyntheticVariableMappings(
        JsonElement instructionBits,
        Dictionary<string, List<LlvmEncodingBit>> fieldBits)
    {
        var bitIndex = 0;
        foreach (var bit in instructionBits.EnumerateArray())
        {
            if (bit.ValueKind == JsonValueKind.Object
                && OptionalString(bit, "kind") == "var"
                && OptionalString(bit, "var") is { } name
                && IsSyntheticEncodedBit(name, bitIndex))
            {
                if (!fieldBits.TryGetValue(name, out var mappings))
                {
                    mappings = [];
                    fieldBits.Add(name, mappings);
                }

                if (mappings.Count == 0)
                {
                    mappings.Add(new LlvmEncodingBit(bitIndex, 0));
                }
            }

            bitIndex++;
        }
    }

    private static bool IsSyntheticEncodedBit(string name, int bitIndex)
    {
        return (name, bitIndex) switch
        {
            ("ZAda", 0)
            or ("imm", 0)
            or ("i1", 5)
            or ("index", 8)
            or ("rot", 10)
            or ("imm", 16)
            or ("i", 16)
            or ("idx", 14)
            or ("idx", 23)
            or ("iop", 20)
            or ("Q", 30) => true,
            _ => false,
        };
    }

    private static bool TryReadSpecialEncoding(string name, out EncodingSummary encoding)
    {
        if (TryGetPStateRepresentative(name, out var pstateMask, out var pstateValue, out var pstateFields))
        {
            encoding = new EncodingSummary(
                pstateMask,
                pstateValue,
                true,
                true,
                pstateFields.Select(field => field.Name).Distinct(StringComparer.Ordinal)
                    .OrderBy(field => field, StringComparer.Ordinal).ToArray(),
                pstateFields);
            return true;
        }

        if (TryGetDuplicateShape(name, out var duplicateMask, out var duplicateValue))
        {
            encoding = new EncodingSummary(
                duplicateMask,
                duplicateValue,
                true,
                true,
                ["Rd", "Rn"],
                [
                    Field("Rd", 0, 5),
                    Field("Rn", 5, 5),
                ]);
            return true;
        }

        if (TryGetCompareZeroShape(name, out var compareValue))
        {
            encoding = new EncodingSummary(
                0xFFE0FC1Fu,
                compareValue,
                true,
                true,
                ["Rn"],
                [Field("Rn", 5, 5)]);
            return true;
        }

        if (TryGetInsertShape(name, out var insertMask, out var insertValue, out var insertFields))
        {
            encoding = new EncodingSummary(
                insertMask,
                insertValue,
                true,
                true,
                ["Rd", "Rn", "idx", "idx2"],
                insertFields);
            return true;
        }

        encoding = default;
        return false;
    }

    private static bool TryGetPStateRepresentative(
        string name,
        out uint mask,
        out uint value,
        out IReadOnlyList<LlvmEncodingField> fields)
    {
        switch (name)
        {
            case "MSRpstateImm1":
                mask = 0xFFF8F01Fu;
                value = 0xD500401Fu;
                fields =
                [
                    Field("imm", 8, 1),
                    MappedField(
                        "pstatefield",
                        (5, 0), (6, 1), (7, 2),
                        (9, 6), (10, 7), (11, 8),
                        (16, 3), (17, 4), (18, 5)),
                ];
                return true;
            case "MSRpstateImm4":
                mask = 0xFFF8F01Fu;
                value = 0xD500401Fu;
                fields =
                [
                    Field("imm", 8, 4),
                    MappedField(
                        "pstatefield",
                        (5, 0), (6, 1), (7, 2),
                        (16, 3), (17, 4), (18, 5)),
                ];
                return true;
            case "MSRpstatesvcrImm1":
                mask = 0xFFFFF0FFu;
                value = 0xD503407Fu;
                fields =
                [
                    Field("imm", 8, 1),
                    MappedField("pstatefield", (9, 0), (10, 1), (11, 2)),
                ];
                return true;
            default:
                mask = 0;
                value = 0;
                fields = [];
                return false;
        }
    }

    private static bool TryGetDuplicateShape(string name, out uint mask, out uint value)
    {
        (mask, value) = name switch
        {
            "DUPv8i8gpr" => (0xFFE1FC00u, 0x0E010C00u),
            "DUPv16i8gpr" => (0xFFE1FC00u, 0x4E010C00u),
            "DUPv4i16gpr" => (0xFFE3FC00u, 0x0E020C00u),
            "DUPv8i16gpr" => (0xFFE3FC00u, 0x4E020C00u),
            "DUPv2i32gpr" => (0xFFE7FC00u, 0x0E040C00u),
            "DUPv4i32gpr" => (0xFFE7FC00u, 0x4E040C00u),
            "DUPv2i64gpr" => (0xFFEFFC00u, 0x4E080C00u),
            _ => (0u, 0u),
        };
        return mask != 0;
    }

    private static bool TryGetCompareZeroShape(string name, out uint value)
    {
        value = name switch
        {
            "FCMPSri" => 0x1E202008u,
            "FCMPESri" => 0x1E202018u,
            "FCMPDri" => 0x1E602008u,
            "FCMPEDri" => 0x1E602018u,
            "FCMPHri" => 0x1EE02008u,
            "FCMPEHri" => 0x1EE02018u,
            _ => 0,
        };
        return value != 0;
    }

    private static bool TryGetInsertShape(
        string name,
        out uint mask,
        out uint value,
        out IReadOnlyList<LlvmEncodingField> fields)
    {
        var (variableMask, fixedValue, indexWidth, sourceIndexWidth) = name switch
        {
            "INSvi16lane" => (0x001C7BFFu, 0x6E020400u, 3, 3),
            "INSvi32lane" => (0x00187BFFu, 0x6E040400u, 2, 2),
            "INSvi64lane" => (0x00107BFFu, 0x6E080400u, 1, 1),
            _ => (0u, 0u, 0, 0),
        };
        if (variableMask == 0)
        {
            mask = 0;
            value = 0;
            fields = [];
            return false;
        }

        mask = ~variableMask;
        value = fixedValue;
        fields =
        [
            Field("Rd", 0, 5),
            Field("Rn", 5, 5),
            Field("idx", 18 + (3 - indexWidth), indexWidth),
            Field("idx2", 12 + (3 - sourceIndexWidth), sourceIndexWidth),
        ];
        return true;
    }

    private static LlvmEncodingField Field(string name, int encodingBit, int width)
    {
        return new LlvmEncodingField(
            name,
            Enumerable.Range(0, width)
                .Select(fieldBit => new LlvmEncodingBit(encodingBit + fieldBit, fieldBit))
            .ToArray());
    }

    private static LlvmEncodingField MappedField(
        string name,
        params (int EncodingBit, int FieldBit)[] mappings)
    {
        return new LlvmEncodingField(
            name,
            mappings.Select(mapping => new LlvmEncodingBit(mapping.EncodingBit, mapping.FieldBit)).ToArray());
    }

    private static IReadOnlyList<string> ReadStringList(JsonElement record, string propertyName)
    {
        if (!record.TryGetProperty(propertyName, out var values)
            || values.ValueKind != JsonValueKind.Array)
        {
            return [];
        }

        var result = new List<string>();
        foreach (var value in values.EnumerateArray())
        {
            if (value.ValueKind == JsonValueKind.String)
            {
                result.Add(value.GetString() ?? string.Empty);
            }
            else if (value.ValueKind == JsonValueKind.Object)
            {
                result.Add(OptionalString(value, "def") ?? OptionalString(value, "printable") ?? string.Empty);
            }
        }

        return result.Where(value => value.Length != 0).ToArray();
    }

    private static bool HasNamedRegister(
        JsonElement record,
        string propertyName,
        string expectedName)
    {
        if (!record.TryGetProperty(propertyName, out var values)
            || values.ValueKind != JsonValueKind.Array)
        {
            return false;
        }

        foreach (var value in values.EnumerateArray())
        {
            var name = value.ValueKind == JsonValueKind.String
                ? value.GetString()
                : value.ValueKind == JsonValueKind.Object
                    ? OptionalString(value, "def") ?? OptionalString(value, "name")
                    : null;
            if (string.Equals(name, expectedName, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }

    private static IReadOnlyList<LlvmOperandRecord> ReadOperands(
        JsonElement root,
        IReadOnlySet<string> names)
    {
        var operands = new List<LlvmOperandRecord>();
        foreach (var name in names.OrderBy(name => name, StringComparer.Ordinal))
        {
            if (!root.TryGetProperty(name, out var record)
                || record.ValueKind != JsonValueKind.Object)
            {
                continue;
            }

            operands.Add(new LlvmOperandRecord(
                name,
                ReadString(record, "OperandType"),
                ReadString(record, "DecoderMethod"),
                ReadString(record, "EncoderMethod"),
                ReadString(record, "PrintMethod"),
                ReadPrintable(record, "ParserMatchClass") ?? string.Empty,
                ReadPrintable(record, "RegClass") ?? string.Empty,
                ReadPrintable(record, "ElementSize") ?? string.Empty,
                ReadPrintable(record, "Type") ?? string.Empty,
                ReadStringList(record, "!superclasses")));
        }

        return operands;
    }

    private static string ReadString(JsonElement record, string propertyName)
    {
        return OptionalString(record, propertyName) ?? string.Empty;
    }

    private static IReadOnlyList<LlvmOperandBinding> ReadOperandBindings(JsonElement record)
    {
        var bindings = new Dictionary<string, LlvmOperandBinding>(StringComparer.Ordinal);
        ReadOperandList(record, "OutOperandList", "out", bindings);
        ReadOperandList(record, "InOperandList", "in", bindings);
        return bindings.Values.ToArray();
    }

    private static void ReadOperandList(
        JsonElement record,
        string propertyName,
        string direction,
        Dictionary<string, LlvmOperandBinding> bindings)
    {
        if (!record.TryGetProperty(propertyName, out var operandList)
            || operandList.ValueKind != JsonValueKind.Object
            || !operandList.TryGetProperty("args", out var arguments)
            || arguments.ValueKind != JsonValueKind.Array)
        {
            return;
        }

        foreach (var argument in arguments.EnumerateArray())
        {
            if (argument.ValueKind != JsonValueKind.Array || argument.GetArrayLength() < 2)
            {
                continue;
            }

            var type = ReadOperandType(argument[0]);
            var name = argument[1].ValueKind == JsonValueKind.String ? argument[1].GetString() : null;
            if (string.IsNullOrEmpty(type) || string.IsNullOrEmpty(name))
            {
                continue;
            }

            if (bindings.TryGetValue(name, out var existing))
            {
                bindings[name] = existing with
                {
                    Direction = existing.Direction == direction ? direction : "inout",
                };
            }
            else
            {
                bindings.Add(name, new LlvmOperandBinding(name, type, direction));
            }
        }
    }

    private static string? ReadOperandType(JsonElement operand)
    {
        if (operand.ValueKind == JsonValueKind.String)
        {
            return operand.GetString();
        }

        if (operand.ValueKind != JsonValueKind.Object)
        {
            return null;
        }

        var direct = OptionalString(operand, "def");
        if (direct is not null)
        {
            return direct;
        }

        if (OptionalString(operand, "kind") == "dag"
            && operand.TryGetProperty("operator", out var operatorElement))
        {
            return OptionalString(operatorElement, "def")
                ?? OptionalString(operatorElement, "printable");
        }

        return OptionalString(operand, "printable");
    }

    private static bool ReadFlag(JsonElement record, string propertyName)
    {
        return ReadNullableFlag(record, propertyName) == true;
    }

    private static bool? ReadNullableFlag(JsonElement record, string propertyName)
    {
        if (!record.TryGetProperty(propertyName, out var value))
        {
            return null;
        }

        return value.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            JsonValueKind.Number when value.TryGetInt32(out var number) => number != 0,
            JsonValueKind.Null => null,
            _ => null,
        };
    }

    private static string? OptionalString(JsonElement record, string propertyName)
    {
        return record.TryGetProperty(propertyName, out var value)
            && value.ValueKind == JsonValueKind.String
            ? value.GetString()
            : null;
    }

    private static string? ReadPrintable(JsonElement record, string propertyName)
    {
        if (!record.TryGetProperty(propertyName, out var value))
        {
            return null;
        }

        if (value.ValueKind == JsonValueKind.String)
        {
            return value.GetString();
        }

        return value.ValueKind == JsonValueKind.Object
            ? OptionalString(value, "printable")
            : null;
    }

    private static string Mnemonic(string assembly)
    {
        var separator = assembly.IndexOfAny([' ', '\t', '{']);
        return (separator < 0 ? assembly : assembly[..separator]).ToLowerInvariant();
    }

    private static void ValidateExactOverlaps(IReadOnlyList<LlvmInstructionRecord> instructions)
    {
        var groups = instructions
            .Where(record => !record.IsPseudo && record.HasBits && record.HasCompleteEncoding)
            .GroupBy(record => new EncodingKey(record.Mask, record.Value));
        foreach (var group in groups.Where(group => group.Count() > 1))
        {
            var names = group.Select(record => record.Name).OrderBy(name => name, StringComparer.Ordinal).ToArray();
            if (allowedExactOverlaps.Any(allowed => allowed.OrderBy(name => name, StringComparer.Ordinal).SequenceEqual(names)))
            {
                continue;
            }

            throw new InvalidDataException(
                $"Unapproved exact encoding overlap 0x{group.Key.Mask:X8}/0x{group.Key.Value:X8}: {string.Join(", ", names)}.");
        }
    }

    private static string Flags(LlvmInstructionRecord record)
    {
        var flags = new List<string>();
        if (record.IsBranch)
        {
            flags.Add("A64GeneratedFlags.Branch");
        }

        if (record.IsCall)
        {
            flags.Add("A64GeneratedFlags.Call");
        }

        if (record.IsReturn)
        {
            flags.Add("A64GeneratedFlags.Return");
        }

        if (record.IsCompare)
        {
            flags.Add("A64GeneratedFlags.Compare");
        }

        if (record.IsBarrier)
        {
            flags.Add("A64GeneratedFlags.Barrier");
        }

        if (record.IsTerminator)
        {
            flags.Add("A64GeneratedFlags.Terminator");
        }

        if (record.HasSideEffects)
        {
            flags.Add("A64GeneratedFlags.SideEffects");
        }

        if (record.Assembly.Contains('!'))
        {
            flags.Add("A64GeneratedFlags.WritesBack");
        }

        if (record.Superclasses.Any(superclass =>
                superclass.Contains("Exclusive", StringComparison.Ordinal)
                || superclass.Contains("CAS", StringComparison.Ordinal)
                || superclass.Contains("Atomic", StringComparison.Ordinal)))
        {
            flags.Add("A64GeneratedFlags.Atomic");
        }

        if (record.Superclasses.Any(superclass =>
                superclass is "BaseSystemI" or "ExceptionGeneration" or "SpecialReturn"))
        {
            flags.Add("A64GeneratedFlags.System");
        }

        if (record.MayLoad == true)
        {
            flags.Add("A64GeneratedFlags.Load");
        }

        if (record.MayStore == true)
        {
            flags.Add("A64GeneratedFlags.Store");
        }

        if (record.ReadsNzcv)
        {
            flags.Add("A64GeneratedFlags.ReadsNzcv");
        }

        if (record.WritesNzcv)
        {
            flags.Add("A64GeneratedFlags.WritesNzcv");
        }

        if (record.ReadsFpcr)
        {
            flags.Add("A64GeneratedFlags.ReadsFpcr");
        }

        if (record.WritesFpcr)
        {
            flags.Add("A64GeneratedFlags.WritesFpcr");
        }

        if (record.ReadsFfr)
        {
            flags.Add("A64GeneratedFlags.ReadsFfr");
        }

        if (record.WritesFfr)
        {
            flags.Add("A64GeneratedFlags.WritesFfr");
        }

        if (record.MayRaiseFpException)
        {
            flags.Add("A64GeneratedFlags.MayRaiseFpException");
        }

        return flags.Count == 0
            ? "A64GeneratedFlags.None"
            : string.Join(" | ", flags);
    }

    private static string FieldEncoding(LlvmInstructionRecord record)
    {
        return string.Join(
            ';',
            record.Fields.Select(field =>
                $"{field.Name}="
                + string.Join(',', field.Bits.Select(bit => $"{bit.EncodingBit}:{bit.FieldBit}"))));
    }

    private static string OperandBindings(LlvmInstructionRecord record)
    {
        return string.Join(
            '|',
            record.Bindings.Select(binding => $"{binding.Name}:{binding.Type}:{binding.Direction}"));
    }

    private static string Quote(string value)
    {
        return '"' + value
            .Replace("\\", "\\\\", StringComparison.Ordinal)
            .Replace("\"", "\\\"", StringComparison.Ordinal)
            .Replace("\r", "\\r", StringComparison.Ordinal)
            .Replace("\n", "\\n", StringComparison.Ordinal)
            .Replace("\t", "\\t", StringComparison.Ordinal)
            + '"';
    }

    private readonly record struct RegisterConstraintPlan(
        int MinimumIndex,
        int MaximumIndex,
        int Step,
        uint AllowedMask)
    {
        public static RegisterConstraintPlan Any => new(0, 31, 1, 0);
    }

    private readonly record struct ModifiedShape(
        string RegisterField,
        string ModifierField,
        string RegisterType);

    private sealed record TypedBindingPlan(
        string Name,
        string Type,
        string Direction,
        string? TiedTo,
        string PredicateMode,
        int FieldIndex,
        int SecondaryFieldIndex,
        string Kind,
        int FieldWidth,
        int Scale,
        int RegisterWidth,
        int RegisterIndexBias,
        int RegisterIndexScale,
        string RegisterClass,
        bool AllowsStackPointer,
        bool AllowsZeroRegister,
        RegisterConstraintPlan RegisterConstraint,
        int ShapeCount,
        int ElementWidth,
        int GroupStride,
        int FractionalBits,
        int LaneCount,
        bool IsPageRelative,
        int PcRelativeScale,
        bool IsSigned,
        string ImmediateSemanticKind,
        string EnumKind,
        string SemanticDomain,
        string MatrixRegisterKind,
        string FixedModifierKind,
        int FixedModifierAmount);

    private readonly record struct EncodingKey(uint Mask, uint Value);

    private readonly record struct EncodingSummary(
        uint Mask,
        uint Value,
        bool HasBits,
        bool IsComplete,
        IReadOnlyList<string> VariableFields,
        IReadOnlyList<LlvmEncodingField> Fields);
}

