    string? InputOperands,
    string? OutputOperands,
    string Constraints,
    bool IsPseudo,
    bool IsCodeGenOnly,
    bool IsAsmParserOnly,
    bool IsBranch,
    bool IsCall,
    bool IsReturn,
    bool IsCompare,
    bool IsBarrier,
    bool IsTerminator,
    bool HasSideEffects,
    bool ReadsNzcv,
    bool WritesNzcv,
    bool ReadsFpcr,
    bool WritesFpcr,
    bool ReadsFfr,
    bool WritesFfr,
